import {ITEMS} from './inventory.js';
export const SAVE_KEY='hanskoy-game.save.v1', BACKUP_KEY=SAVE_KEY+'.backup';
const stages=new Set(['safe','offer','smith','armed','wolf','report','forest','carcasses','delivery','complete','mary_offer','water','ambush','water_return','mary_done','witch']);
const finite=(n,min=-1e8,max=1e8)=>Number.isFinite(n)&&n>=min&&n<=max;
const vector=v=>Array.isArray(v)&&v.length===3&&v.every(n=>finite(n,-10000,10000));
function require(ok){if(!ok)throw new Error('Файл повреждён или не является сохранением этой версии игры.')}
function actor(a){require(a&&vector(a.position)&&typeof a.visible==='boolean'&&typeof a.hit==='boolean');for(const k of ['hp','maxHp','heading','generation','cooldown','timer'])require(a[k]===undefined||finite(a[k]));for(const k of ['home','target','patrolTarget','aggro','aggroOrigin'])require(a[k]===null||vector(a[k]));require(a.mode===undefined||['attack','return'].includes(a.mode))}
function projectile(b){require(b&&vector(b.position)&&vector(b.velocity)&&finite(b.age,0,10)&&finite(b.damage,0,1000));}
export function validateSave(s){require(s?.game==='hanskoy-game'&&s.version===1&&typeof s.savedAt==='string'&&Number.isFinite(Date.parse(s.savedAt)));const p=s.chapter?.p;require(p&&stages.has(p.stage)&&[null,'sword','bow','mage'].includes(p.classId));require(Number.isInteger(p.level)&&p.level>=1&&p.level<=10000&&finite(p.xp,0,249)&&Number.isInteger(p.pendingLevels)&&p.pendingLevels>=0&&p.pendingLevels<p.level);require(typeof p.rejected==='boolean'&&typeof p.wolfDead==='boolean'&&finite(p.arrows,0,1000000));require(Array.isArray(p.rewards)&&p.rewards.length<=20000&&p.rewards.every(id=>typeof id==='string'&&id.length<150));const slots=s.chapter.slots;require(Array.isArray(slots)&&slots.length===18);slots.forEach((item,i)=>{if(item===null)return;require(item&&Object.hasOwn(ITEMS,item.id)&&Number.isInteger(item.count)&&item.count>0&&item.count<=1000000);require(i>=6||ITEMS[item.id].slot===i)});require(slots.filter(i=>i&&['sword','bow','mage'].includes(i.id)).every(i=>i.id===p.classId));require(Array.isArray(s.chapter.bullets)&&s.chapter.bullets.length<=100);s.chapter.bullets.forEach(b=>{projectile(b);require(typeof b.arrow==='boolean'&&finite(b.delay,0,1))});for(const k of ['lastAttack','lastHurt','attackTime'])require(finite(s.chapter[k]));const v=s.player?.vitals;require(v&&vector(s.player.position)&&finite(s.player.yaw)&&finite(s.player.pitch,-1.35,1.35));for(const [key,max] of [['hp','maxHp'],['mana','maxMana'],['stamina','maxStamina']]){require(finite(v[max],100,100100)&&finite(v[key],0,v[max]))}require(finite(v.height,0,10)&&finite(v.velocity,-100,100));require(finite(s.elapsed,0)&&Number.isInteger(s.seed)&&s.seed>=0&&s.seed<=4294967295&&typeof s.muted==='boolean');require(Array.isArray(s.actors)&&s.actors.length===8);s.actors.forEach(actor);
const w=s.world;require(w&&typeof w.inside==='boolean'&&typeof w.witchActive==='boolean'&&finite(w.time,0)&&Array.isArray(w.mobs)&&w.mobs.length===(w.witchActive?36:35));const expected=new Set(Array.from({length:35},(_,i)=>i<30?'deep-'+(i%3===0?'hare':'wolf')+'-'+i:'deep-raven-'+i));if(w.witchActive)expected.add('witch');w.mobs.forEach(a=>{actor(a);require(expected.delete(a.id))});require(expected.size===0);actor(w.witch);require(Array.isArray(w.drops)&&w.drops.length<=2000);w.drops.forEach(d=>require(['carcass','fang'].includes(d.id)&&vector(d.position)&&finite(d.phase)));require(Array.isArray(w.shots)&&w.shots.length<=100);w.shots.forEach(b=>{projectile(b);require(typeof b.large==='boolean')});
const e=s.encounter;require(e&&typeof e.started==='boolean'&&Array.isArray(e.mobs)&&e.mobs.length===(e.started?3:0));e.mobs.forEach((a,i)=>{actor(a);require(a.id==='lake-wolf-'+i)});require(!['ambush','water_return','mary_done'].includes(p.stage)||e.started);const inDeep=s.player.position[0]>180;require(inDeep===w.inside);return s}
export function encodeSave(state){return JSON.stringify(validateSave({...state,game:'hanskoy-game',version:1,savedAt:new Date().toISOString()}))}
export function decodeSave(text){if(typeof text!=='string'||text.length>2000000)throw new Error('Файл сохранения слишком большой.');return validateSave(JSON.parse(text))}
export function saveStore(storage){return {read(){let corrupt=false;for(const key of [SAVE_KEY,BACKUP_KEY]){const raw=storage.getItem(key);if(!raw)continue;try{return {data:decodeSave(raw),backup:key===BACKUP_KEY}}catch{corrupt=true}}return {data:null,corrupt}},write(state){const raw=encodeSave(state),old=storage.getItem(SAVE_KEY);if(old){try{decodeSave(old);storage.setItem(BACKUP_KEY,old)}catch(error){if(error?.name==='QuotaExceededError')throw error}}storage.setItem(SAVE_KEY,raw);return raw},clear(){storage.removeItem(SAVE_KEY);storage.removeItem(BACKUP_KEY)}}}
